# Let's look at the distribution of word lengths in responses
from collections import Counter
word_counts = Counter()
for line in lines:
    if line.startswith('assistant:'):
        words = line.replace('assistant:', '').strip().split()
        word_counts[len(words)] += 1

print("Response length distribution (top 20):")
for length, count in word_counts.most_common(20):
    print(f"  {length} words: {count} times")

print("---")
# Let's see if there's a consistent mapping - look at repeated patterns
# First, let's check if the same user question gets the same response
user_responses = {}
for i in range(0, len(lines), 3):
    if i+1 < len(lines) and lines[i].startswith('user:') and lines[i+1].startswith('assistant:'):
        user_q = lines[i]
        assistant_r = lines[i+1]
        if user_q not in user_responses:
            user_responses[user_q] = []
        user_responses[user_q].append(assistant_r)

# Find questions that appear multiple times
for q, responses in user_responses.items():
    if len(responses) > 1:
        print(f"Question: {q}")
        for r in responses:
            print(f"  Response: {r}")
        print()
```

